/* ---------- Finance 15 (Ledger A, Rockefeller) shot functions ---------- */
const terms = (t, d, L, list) => list.map(([lab, q, x, y, st, hold]) => { const a = ph(L, q, 0.6); return T(lab, x, y, span(t, a, Math.min(d - 0.25, a + (hold || 5.5))), st || YT); });
const bigWord = (t, a, b, txtS, cx, cy, col, size) => x => { const s = span(t, a, b); if (s <= 0.01) return; x.save(); x.translate(cx, cy); x.scale(s, s); x.rotate(-0.04); x.font = `${size || 64}px ${HAND}`; x.textAlign = 'center'; x.textBaseline = 'middle'; x.lineWidth = 10; x.strokeStyle = '#1e1612'; x.strokeText(txtS, 0, 0); x.fillStyle = col || '#f2c83a'; x.fillText(txtS, 0, 0); x.restore(); };
// red ink stamp (ledger stamp)
const inkStamp = (t, a, word, cx, cy) => x => { if (t < a) return; const k = k01(t, a, a + 0.18), fade = 1 - k01(t, a + 2.6, a + 3.1); if (fade <= 0) return; const sc = 1.6 - 0.6 * E(k); x.save(); x.globalAlpha = 0.9 * fade; x.translate(cx, cy); x.rotate(-0.12); x.scale(sc, sc);
  x.strokeStyle = '#c2372d'; x.lineWidth = 7; x.strokeRect(-130, -46, 260, 92); x.lineWidth = 3; x.strokeRect(-118, -36, 236, 72); x.fillStyle = '#c2372d'; x.font = `${word.length > 10 ? 30 : 40}px ${HAND}`; x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillText(word, 0, 2); x.restore(); };
// year stamp top-left: "1855" etc
const yearTag = (t, d, y) => T(y, 120, 70, span(t, 0.3, d - 0.3), BT);
const sep = k => x => { if (k <= 0) return; x.save(); x.globalCompositeOperation = 'multiply'; x.globalAlpha = 0.18 * k; x.fillStyle = '#c89a5a'; x.fillRect(0, 0, W, H); x.restore(); };
// camera sequence: seq = [[at, [pos, look], [pos, look]], ...] with z relative to the set's z0
const camSeq = (s, t, d, seq) => { const z = s.z0 || 0; let i = 0; while (i < seq.length - 1 && t >= seq[i + 1][0]) i++; const [a, A, B] = seq[i]; const b = i < seq.length - 1 ? seq[i + 1][0] : d; const zz = q => [[q[0][0], q[0][1], q[0][2] + z], [q[1][0], q[1][1], q[1][2] + z]]; cl(s, k01(t, a, b), zz(A), zz(B)); };
// generic standing actor (z relative to z0)
const act = (s, key, x, dz, o, t, L, who, h) => sp(s, key, x, (s.z0 || 0) + dz, Object.assign({ view: 'q' }, o), t, L, who, h || 1.7);
const setPage = (s, rows) => { const k = JSON.stringify(rows); if (s._pg === k) return; s._pg = k; s.ledger.userData.page.userData.draw({ rows }); };
const LED0 = [['Sept 26 1855', 'job day'], ['wages', '50c / day'], ['washing', '10c'], ['Sunday school', '5c'], ['to the poor', '10c']];
const dimeFx = (t, a, cx, cy, b = 1e9) => x => { if (t < a || t > b) return; const k = k01(t, a, a + 0.7); x.save(); x.translate(cx, cy - 40 * (1 - E(k))); x.rotate(t * 3); x.scale(Math.cos(t * 6), 1); x.fillStyle = '#d8dce0'; x.strokeStyle = '#6a6e72'; x.lineWidth = 4; x.beginPath(); x.arc(0, 0, 26, 0, TAU); x.fill(); x.stroke(); x.fillStyle = '#6a6e72'; x.font = `20px ${HAND}`; x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillText('10¢', 0, 1); x.restore(); };

